const body = $json.body || {};
const isManual = Boolean($json.headers || $json.query || $json.params || $json.body);
const execute = body.execute === true || body.execute === 'true';
const force = body.force === true || body.force === 'true';
const limit = Number.parseInt(body.limit || '', 10);
const brand = String(body.brand || '').trim().toUpperCase();

return [{ json: {
  source: isManual ? 'manual' : 'schedule',
  dry_run: isManual ? !execute : false,
  force,
  limit: Number.isInteger(limit) && limit > 0 ? Math.min(limit, 100) : '',
  brand: ['KIA', 'HYUNDAI'].includes(brand) ? brand : ''
} }];

const row = $input.first()?.json || {};

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  }
  return [];
}

const leads = asArray(row.leads);
const dispatches = asArray(row.dispatches);
const dispatchByLeadId = new Map(
  dispatches
    .filter(dispatch => dispatch && dispatch.lead_id)
    .map(dispatch => [String(dispatch.lead_id), dispatch])
);
const dryRun = row.dry_run === true || String(row.dry_run) === 'true';
const force = row.force_dispatch === true || String(row.force_dispatch) === 'true';
const enabled = row.dispatch_enabled === true || String(row.dispatch_enabled) === 'true';
const outboundUrl = 'http://localhost:5678/webhook/quicklink-lead-inbound';
const sleepMs = 100;
const maxRunMs = 240000;
const httpTimeoutMs = 15000;
const dispatchConcurrency = 2;
const startedAtMs = Date.now();
const results = [];
const helpers = this.helpers;

const SAFETY_REAL_SENDS_ENABLED = true;
const SEND_TIME_ZONE = 'America/Guayaquil';
const SEND_WINDOW_LABEL = '09:30-16:00 America/Guayaquil';
const SEND_WINDOW_START_MINUTES = 9 * 60 + 30;
const SEND_WINDOW_END_MINUTES = 16 * 60;

function normalizeDigits(value) {
  return String(value || '').replace(/\D/g, '');
}

function ecuadorMinutesNow() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: SEND_TIME_ZONE,
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date());
  const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
  const hour = Number(values.hour === '24' ? '0' : values.hour);
  const minute = Number(values.minute || '0');
  return hour * 60 + minute;
}

function elapsedMs() {
  return Date.now() - startedAtMs;
}

function remainingMs() {
  return maxRunMs - elapsedMs();
}

function hasTimeForAnotherSend() {
  return dryRun || remainingMs() > httpTimeoutMs + sleepMs + 5000;
}

function resultBase(lead, requestId, batchKey) {
  return {
    quicklink_id: lead.quicklink_id,
    marca: lead.marca,
    request_id: requestId || null,
    batch_key: batchKey || null,
  };
}

const currentEcuadorMinutes = ecuadorMinutesNow();
const insideSendWindow = currentEcuadorMinutes >= SEND_WINDOW_START_MINUTES && currentEcuadorMinutes <= SEND_WINDOW_END_MINUTES;

if (!dryRun && !SAFETY_REAL_SENDS_ENABLED) {
  return [{ json: {
    status: 'dispatch_safety_blocked',
    reason: 'real_sends_disabled_while_resolving_error',
    dry_run: dryRun,
    dispatch_enabled: enabled,
    force_dispatch: force,
    send_window: SEND_WINDOW_LABEL,
    lead_count: leads.length,
    sent_count: 0,
    failed_count: 0,
    skipped_count: leads.length,
    deferred_count: 0,
    max_run_ms: maxRunMs,
    http_timeout_ms: httpTimeoutMs,
    results: leads.slice(0, 20).map(lead => ({
      quicklink_id: lead.quicklink_id,
      marca: lead.marca,
      status: 'safety_blocked',
    })),
  } }];
}

if (!dryRun && !insideSendWindow) {
  return [{ json: {
    status: 'dispatch_window_blocked',
    reason: 'outside_ecuador_send_window',
    dry_run: dryRun,
    dispatch_enabled: enabled,
    force_dispatch: force,
    send_window: SEND_WINDOW_LABEL,
    lead_count: leads.length,
    sent_count: 0,
    failed_count: 0,
    skipped_count: leads.length,
    deferred_count: 0,
    max_run_ms: maxRunMs,
    http_timeout_ms: httpTimeoutMs,
  } }];
}

if (!dryRun && !enabled && !force) {
  return [{ json: {
    status: 'dispatch_blocked',
    reason: 'campaign.outbound.dispatch-enabled=false',
    dry_run: dryRun,
    dispatch_enabled: enabled,
    force_dispatch: force,
    lead_count: 0,
    sent_count: 0,
    failed_count: 0,
    skipped_count: 0,
    deferred_count: 0,
    max_run_ms: maxRunMs,
    http_timeout_ms: httpTimeoutMs,
  } }];
}

const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
let stoppedByTimeBudget = false;
let nextLeadIndex = 0;

async function dispatchLead(lead) {
  const leadId = String(lead.lead_id || lead.id || '').trim();
  const dispatch = dispatchByLeadId.get(leadId) || {};
  const requestId = String(dispatch.request_id || '').trim();
  const batchKey = String(row.batch_key || '').trim();
  const base = resultBase(lead, requestId, batchKey);
  const agentPhone = String(lead.telefono_agente || '').trim();
  const agentDigits = normalizeDigits(agentPhone);

  if (!dryRun && !hasTimeForAnotherSend()) {
    stoppedByTimeBudget = true;
    results.push({
      ...base,
      status: 'deferred',
      error: 'dispatch_time_budget_exhausted',
      elapsed_ms: elapsedMs(),
    });
    return;
  }

  if (agentDigits.length < 9 || agentDigits.length > 15) {
    results.push({
      ...base,
      status: 'skipped',
      error: agentPhone ? 'invalid_agent_phone' : 'missing_agent_phone',
    });
    return;
  }

  const payload = {
    phone: agentPhone,
    marca: lead.marca,
    quicklink_id: lead.quicklink_id,
    nombre_cliente: lead.nombre_cliente,
    modelo: lead.modelo,
    source: 'outbound-dispatcher',
    request_id: requestId,
    batch_key: batchKey
  };

  if (dryRun) {
    results.push({
      ...base,
      status: 'dry_run',
    });
    return;
  }

  if (!requestId) {
    results.push({
      ...base,
      status: 'failed',
      error: 'missing_dispatch_request_id',
    });
    return;
  }

  try {
    const timeout = Math.min(httpTimeoutMs, Math.max(1000, remainingMs() - 3000));
    const response = await helpers.httpRequest({
      method: 'POST',
      url: outboundUrl,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      timeout,
      ignoreHttpStatusErrors: true
    });
    results.push({ ...base, status: 'sent', response: String(response).slice(0, 120), elapsed_ms: elapsedMs() });
  } catch (error) {
    results.push({ ...base, status: 'failed', error: String(error?.message || error).slice(0, 180), elapsed_ms: elapsedMs() });
  }

  if (sleepMs > 0) await delay(sleepMs);
}

async function worker() {
  while (nextLeadIndex < leads.length) {
    const currentIndex = nextLeadIndex;
    nextLeadIndex += 1;
    await dispatchLead(leads[currentIndex]);
  }
}

const workerCount = dryRun ? 1 : Math.min(dispatchConcurrency, leads.length);
if (workerCount > 0) {
  await Promise.all(Array.from({ length: workerCount }, () => worker()));
}

const sentCount = results.filter(r => r.status === 'sent').length;
const failedCount = results.filter(r => r.status === 'failed').length;
const skippedCount = results.filter(r => r.status === 'skipped').length;
const deferredCount = results.filter(r => r.status === 'deferred').length;
const status = dryRun
  ? 'dispatch_dry_run'
  : (stoppedByTimeBudget || deferredCount ? 'dispatch_deferred' : (failedCount ? 'dispatch_partial' : 'dispatch_ok'));

return [{ json: {
  status,
  dry_run: dryRun,
  dispatch_enabled: enabled,
  force_dispatch: force,
  source: row.source,
  brand: row.brand || null,
  batch_key: row.batch_key || null,
  batch_limit: row.batch_limit,
  send_window: SEND_WINDOW_LABEL,
  lead_count: leads.length,
  dispatch_count: dispatches.length,
  sent_count: sentCount,
  failed_count: failedCount,
  skipped_count: skippedCount,
  deferred_count: deferredCount,
  dispatch_concurrency: dispatchConcurrency,
  max_run_ms: maxRunMs,
  http_timeout_ms: httpTimeoutMs,
  elapsed_ms: elapsedMs(),
  results: results.slice(0, 20)
} }];
